insert  into `uploaded_table1`(`id`,`owner_email`,`filename`,`filetype`,`keyword`,`original_data`,`encrypted_data`,`secret_key`,`trapdoor_key`,`trapdoor_status`,`uploaded_at`,`access_status`) values (1,'sai@gmail.com','ss.txt','text/plain','Note','Executed SQL Statement : truncate table `bankproject`.`userdetails` \r\nError Number : 1701 \r\nError Message: Cannot truncate a table referenced in a foreign key constraint (`bankproject`.`transactions`, CONSTRAINT `transactions_ibfk_1` FOREIGN KEY (`accountno`) REFERENCES `bankproject`.`userdetails` (`accountno`)) \r\n','','VK3Rp3Dw6ZcGBjBXFAnr7Fibl28TTcM/5W6z+duWMEs=','TDK-1772168581984','APPROVED','2026-02-27 10:32:39','PENDING'),(2,'siva@gmail.com','xml.txt','text/plain','Key','<!DOCTYPE web-app PUBLIC\r\n \"-//Sun Microsystems, Inc.//DTD Web Application 2.3//EN\"\r\n \"http://java.sun.com/dtd/web-app_2_3.dtd\" >\r\n\r\n<web-app>\r\n	<display-name>Archetype Created Web Application</display-name>\r\n	<!--  <servlet>\r\n		<servlet-name>ERegister</servlet-name>\r\n		<display-name>ERegister</display-name>\r\n		<description></description>\r\n		<servlet-class>com.employee.ERegister</servlet-class>\r\n	</servlet>\r\n	<servlet-mapping>\r\n		<servlet-name>ERegister</servlet-name>\r\n		<url-pattern>/ERegister</url-pattern>\r\n	</servlet-mapping>\r\n	-->\r\n	<!-- <servlet>\r\n		<servlet-name>ManagerLogin</servlet-name>\r\n		<display-name>ManagerLogin</display-name>\r\n		<servlet-class>com.manager.ManagerLogin</servlet-class>\r\n	</servlet>\r\n	<servlet-mapping>\r\n		<servlet-name>ManagerLogin</servlet-name>\r\n		<url-pattern>/ManagerLogin</url-pattern>\r\n	</servlet-mapping>\r\n	-->\r\n</web-app>\r\n','','WSW9HQIW1tNyAL6AIIT0DmTLuHzdBBHxzrftoP5HrVo=','TDK-1775723279437','APPROVED','2026-02-27 15:51:22','PENDING');

