insert  into `uploaded_table3`(`id`,`owner_email`,`filename`,`filetype`,`keyword`,`original_data`,`encrypted_data`,`secret_key`,`trapdoor_key`,`trapdoor_status`,`uploaded_at`) values (1,'siva@gmail.com','texts.txt','text/plain','Keyed','user should upload filename,custom_filename , original data timestamp and with some other details\r\nwhile uploading the data if the upload file is less than 2mb it should directly upload if the file is more than 2 mb is should warns the sdn , the file size is more than 2mb\r\nand also if the file is more than 2mb while uploading \r\na pop should appear in that pop 2 options should display \r\napprove or reject \r\nif user click the approve \r\nit should take to the payment process, in that payment cardno, bank name, emailid and a random transaction id details should display after user finish the transaction he can upload the data \r\nand sdn can view the details of the transaction \r\nand display sessions also with user email id \r\n\r\n\r\ni want that while admin click approve that time only QR should generate while clicking on QR or scanning QR it should generate the otp\r\n\r\n\r\nuser register with username, email, password, mobile no, Address  then IoT should approve the user register request IoT should share the otp as QR code when user scan the QR code or click on QR code it should show the otp then user should login with email, password, otp.  whenever the user login then the new otp should come  \r\n\r\ngive me code in Servlet, JSP and Database  \r\n\r\ngive me full codes and pages from start to end  ','','TGXdipRoCH/9EJdHGjLr9Gm3XB9aQ+MwbnvyZWbhFbg=',NULL,'PENDING','2026-02-27 15:52:03');

/*Table structure for table `userdetails` */

DROP TABLE IF EXISTS `userdetails`;

CREATE TABLE `userdetails` (
  `id` int(20) NOT NULL AUTO_INCREMENT,
